        if any(type(value) is not int for value in paid.values()):
            errors.append(_error(
                "NON_INTEGER_CENTS",
                "paid",
                "Amounts paid must be integer cents",
            ))
        elif sum(paid.values()) != total:
            errors.append(_error(
                "PAYMENTS_DONT_SUM",
                "paid",
                "Amounts paid do not sum to total",
            ))

